import { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { barbershopsAPI, appointmentsAPI } from '../lib/api';
import { useAuth } from '../hooks/useAuth';

export default function BookingPage({ shop, service, navigate }) {
  const { user } = useAuth();
  const location = useLocation();
  const locationState = location.state || {};
  const activeShop = shop || locationState.shop;
  const activeService = service || locationState.service;
  const [selectedDate, setSelectedDate] = useState('');
  const [selectedTime, setSelectedTime] = useState('');
  const [slots, setSlots] = useState([]);
  const [availabilityError, setAvailabilityError] = useState('');
  const [availabilityAttempt, setAvailabilityAttempt] = useState(0);
  const [loading, setLoading] = useState(false);
  const [confirming, setConfirming] = useState(false);
  const [toast, setToast] = useState('');

  const showToast = (msg) => { setToast(msg); setTimeout(() => setToast(''), 2600); };

  const dates = Array.from({ length: 7 }, (_, i) => {
    const d = new Date(); d.setDate(d.getDate() + i);
    return {
      label: d.toLocaleDateString('pt-BR', { weekday: 'short' }).replace('.', ''),
      num: d.getDate(),
      value: d.toISOString().split('T')[0]
    };
  });

  useEffect(() => {
    if (!selectedDate) { setSelectedDate(dates[0].value); }
  }, []);

  useEffect(() => {
    if (!selectedDate || !activeShop?.id || !activeService?.id) return;
    const controller = new AbortController();
    setLoading(true);
    setSlots([]);
    setAvailabilityError('');
    barbershopsAPI.getAvailability(activeShop.id, selectedDate, activeService.id, controller.signal)
      .then(({ data }) => {
        if (!controller.signal.aborted) setSlots(data.slots || []);
      })
      .catch(() => {
        if (!controller.signal.aborted) {
          setSlots([]);
          setAvailabilityError('Não foi possível carregar os horários. Verifique a conexão e tente novamente.');
        }
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false);
      });
    return () => controller.abort();
  }, [selectedDate, activeShop?.id, activeService?.id, availabilityAttempt]);

  const handleConfirm = async () => {
    if (!user) { navigate('login'); return; }
    if (!selectedDate || !selectedTime || !activeShop || !activeService) return;
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(activeService.id || '')) {
      showToast('Serviço em modo demonstração. Toque em "Tentar" na tela inicial para carregar os dados reais.');
      return;
    }
    if (!slots.some(slot => slot.time === selectedTime && slot.available)) {
      showToast('Este horário não está confirmado como disponível. Atualize os horários e tente novamente.');
      return;
    }
    setConfirming(true);
    try {
      await appointmentsAPI.create({
        barbershop_id: activeShop.id,
        service_id: activeService.id,
        date: selectedDate,
        start_time: selectedTime,
      });
      showToast('✅ Agendamento confirmado!');
      setTimeout(() => navigate('appointments'), 1500);
    } catch (err) {
      showToast(err.response?.data?.error || 'Erro ao agendar. Tente novamente.');
    } finally {
      setConfirming(false);
    }
  };

  return (
    <div className="page">
      {toast && <div className="toast-msg">{toast}</div>}

      <div style={{ padding: '20px', display: 'flex', alignItems: 'center', gap: 14, borderBottom: '1px solid var(--border)' }}>
        <button className="back-btn" onClick={() => navigate('home')} title="Voltar para a tela inicial">🏠</button>
        <span style={{ fontWeight: 600, fontSize: 16 }}>Escolher Horário</span>
      </div>

      <div style={{ padding: '20px' }}>
        {/* Service summary */}
        <div style={{ background: 'var(--dark3)', borderRadius: 12, padding: '14px', marginBottom: 24, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <div style={{ fontSize: 15, fontWeight: 600 }}>{activeService?.name}</div>
            <div style={{ fontSize: 13, color: 'var(--muted)' }}>{activeShop?.name} · {activeService?.duration_minutes} min</div>
          </div>
          <div style={{ fontSize: 18, fontWeight: 700, color: 'var(--gold)' }}>R$ {activeService?.price}</div>
        </div>
        {/* Date picker */}
        <div className="section-title" style={{ marginBottom: 12 }}>Selecione a data</div>
        <div style={{ display: 'flex', gap: 8, overflowX: 'auto', scrollbarWidth: 'none', paddingBottom: 4, marginBottom: 24 }}>
          {dates.map(d => (
            <button key={d.value} onClick={() => { setSelectedDate(d.value); setSelectedTime(''); }}
              style={{
                flexShrink: 0, background: selectedDate === d.value ? 'var(--gold)' : 'var(--dark3)',
                border: `1px solid ${selectedDate === d.value ? 'var(--gold)' : 'var(--border)'}`,
                borderRadius: 10, padding: '8px 14px', cursor: 'pointer', textAlign: 'center', color: selectedDate === d.value ? '#0F0F0F' : 'var(--text)',
              }}>
              <div style={{ fontSize: 10, textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: 2 }}>{d.label}</div>
              <div style={{ fontSize: 17, fontWeight: 600 }}>{d.num}</div>
            </button>
          ))}
        </div>

        {/* Time slots */}
        <div className="section-title" style={{ marginBottom: 12 }}>Horários disponíveis</div>
        {loading ? (
          <div className="loading"><div className="spinner" /><span>Carregando horários...</span></div>
        ) : availabilityError ? (
          <div style={{ marginBottom: 24, color: 'var(--red)', fontSize: 13 }}>
            {availabilityError}{' '}
            <button className="btn-secondary" onClick={() => setAvailabilityAttempt(attempt => attempt + 1)}>
              Tentar novamente
            </button>
          </div>
        ) : slots.length === 0 ? (
          <div style={{ marginBottom: 24, color: 'var(--muted)', fontSize: 13 }}>
            Nenhum horário disponível nesta data.
          </div>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 8, marginBottom: 24 }}>
            {slots.map(slot => (
              <button key={slot.time}
                disabled={!slot.available}
                onClick={() => slot.available && setSelectedTime(slot.time)}
                style={{
                  background: selectedTime === slot.time ? 'var(--gold)' : slot.available ? 'var(--dark3)' : 'var(--dark2)',
                  border: `1px solid ${selectedTime === slot.time ? 'var(--gold)' : 'var(--border)'}`,
                  borderRadius: 10, padding: '10px 4px', fontSize: 13,
                  cursor: slot.available ? 'pointer' : 'not-allowed',
                  color: selectedTime === slot.time ? '#0F0F0F' : slot.available ? 'var(--text)' : 'var(--muted2)',
                  fontFamily: 'DM Sans, sans-serif',
                  textDecoration: !slot.available ? 'line-through' : 'none',
                  opacity: !slot.available ? 0.4 : 1,
                  transition: 'background 0.15s',
                }}>
                {slot.time}
              </button>
            ))}
          </div>
        )}

        {/* Summary */}
        {selectedTime && (
          <div style={{ background: 'var(--dark3)', border: '1px solid var(--gold)', borderRadius: 12, padding: '14px', marginBottom: 16 }}>
            <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 4 }}>Resumo do agendamento</div>
            <div style={{ fontSize: 15, fontWeight: 600 }}>{activeService?.name}</div>
            <div style={{ fontSize: 13, color: 'var(--muted)' }}>
              {activeShop?.name} · {new Date(selectedDate + 'T00:00').toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'long' })} às {selectedTime}
            </div>
            <div style={{ marginTop: 6, fontWeight: 700, color: 'var(--gold)' }}>R$ {activeService?.price}</div>
          </div>
        )}

        <button className="btn-primary"
          disabled={!selectedDate || !selectedTime || confirming || !activeShop || !activeService || !slots.some(slot => slot.time === selectedTime && slot.available)}
          onClick={handleConfirm}>
          {confirming ? 'CONFIRMANDO...' : !user ? 'ENTRAR PARA AGENDAR' : 'CONFIRMAR AGENDAMENTO'}
        </button>
      </div>
    </div>
  );
}
